list_tax_codes.code:
final response = await client.taxCodes.listTaxCodes(queryParams: {'limit': 20});
final taxCodes = (response.map as Map)['tax_codes'] as List;
for (final taxCode in taxCodes) {
  print('${(taxCode as Map)['id']} ${taxCode['name']} ${taxCode['rate']}');
}
final pagination = (response.map as Map)['pagination'] as Map;
print(pagination['total']);

create_tax_code.code:
final response = await client.taxCodes.createTaxCode({
  'tax_code': {
    'name': 'LUXURY',
    'label': 'Luxury goods',
